public class HtmlTreeBuilderTest {

    @Test
    public void testDefaultSettings() {
        HtmlTreeBuilder htmlTreeBuilder = new HtmlTreeBuilder();
        ParseSettings parseSettings = htmlTreeBuilder.defaultSettings();
        assertEquals(3, parseSettings.getDepth());
    }

    @Test
    public void testParseFragment() throws Exception {
        HtmlTreeBuilder htmlTreeBuilder = new HtmlTreeBuilder();
        String inputFragment = "<div><p>Some text</p></div>";
        Element context = null;
        ParseSettings defaultSettings = htmlTreeBuilder.defaultSettings();

        List<Node> nodes = htmlTreeBuilder.parseFragment(inputFragment, context, "https://example.com", defaultSettings);
        assertEquals(1, nodes.size());
    }

    @Test
    public void testInitialiseParse() {
        HtmlTreeBuilder htmlTreeBuilder = new HtmlTreeBuilder();
        ParseSettings parseSettings = htmlTreeBuilder.defaultSettings();

        htmlTreeBuilder.initialiseParse(new InputStreamReader(System.in), "", null);

        String baseUri = "https://example.com";
        Element parser = htmlTreeBuilder.parseFragment("", null, baseUri, null);
        assertEquals("https://example.com", parser.getBaseUri());
    }

    @Test
    public void testProcess() throws Exception {
        HtmlTreeBuilder htmlTreeBuilder = new HtmlTreeBuilder();
        ParseSettings parseSettings = htmlTreeBuilder.defaultSettings();

        String inputFragment = "<p>This is a paragraph</p>";
        Element context = null;
        Element parser = htmlTreeBuilder.parseFragment(inputFragment, context, "https://example.com", parseSettings);

        boolean processed = htmlTreeBuilder.process(parser);
        assertTrue(processed);
    }

    @Test
    public void testProcessWithToken() throws Exception {
        HtmlTreeBuilder htmlTreeBuilder = new HtmlTreeBuilder();
        ParseSettings parseSettings = htmlTreeBuilder.defaultSettings();

        String inputFragment = "<p>This is a paragraph</p>";
        Element context = null;
        Element parser = htmlTreeBuilder.parseFragment(inputFragment, context, "https://example.com", parseSettings);
        Token token = parser.getToken();

        boolean processed = htmlTreeBuilder.process(token);
        assertTrue(processed);
    }

